                    ind_asr[(ds, atk, mid)] = nf / max(nc, 1)

    all_combos = list(itertools.combinations(range(len(ALL_MODELS)), 3))
    n_panels = len(all_combos)
    print(f"Panels: {n_panels}, precomputing ASR for all method × condition × panel...")

    # Precompute: method -> condition -> arrays (asr, keff, eta)
    precomputed = {}
    conditions_list = [(ds, atk) for ds in DATASETS for atk in ATTACKS]

    for method_name, agg_fn in METHODS.items():
        is_thresh = method_name == "threshold_vote"
        precomputed[method_name] = {}

        for ds, atk in conditions_list:
            cond = f"{ds}x{atk}"
            keff_data = mi_data["keff_per_panel"].get(ds, {})
            asrs, keffs, etas = [], [], []

            for combo in all_combos:
                jids = [ALL_MODELS[i] for i in combo]
                if not all((ds, atk, j) in ind_asr for j in jids):
                    continue
                pk = "|".join(jids)
                if pk not in keff_data:
                    continue
                weights = {j: clean_acc.get((j, ds), 0.5) for j in jids}
                asr = compute_panel_asr(jids, clean[ds], attacked[ds][atk],
                                        pairs[ds], agg_fn, weights, is_thresh)
                asrs.append(asr)
                keffs.append(keff_data[pk]["keff"])
                etas.append(max(ind_asr[(ds, atk, j)] for j in jids))

            precomputed[method_name][cond] = {
                "asr": np.array(asrs),
                "keff": np.array(keffs),
                "eta": np.array(etas),
            }

        # Original R²
        r2s = []
        for ds, atk in conditions_list:
            cond = f"{ds}x{atk}"
            d = precomputed[method_name][cond]
            if len(d["asr"]) < 10 or np.std(d["asr"]) < 1e-10:
                continue
            r2s.append(fit_r2(d["asr"], d["keff"], d["eta"]))
        print(f"  {method_name}: mean R² = {np.mean(r2s):.4f} (original, {len(r2s)} conditions)")

    # Bootstrap
    print(f"\nRunning bootstrap (B={B})...")
    rng = np.random.RandomState(SEED)

    boot_r2 = {m: [] for m in METHODS}  # method -> list of mean R²
    boot_r2_per_cond = {m: {f"{ds}x{atk}": [] for ds, atk in conditions_list} for m in METHODS}

    for b in range(B):
        if (b + 1) % 1000 == 0:
            print(f"  bootstrap {b+1}/{B}")

        for method_name in METHODS:
            cond_r2s = []
            for ds, atk in conditions_list:
                cond = f"{ds}x{atk}"
                d = precomputed[method_name][cond]
                n = len(d["asr"])
                if n < 10 or np.std(d["asr"]) < 1e-10:
                    continue
                idx = rng.randint(0, n, size=n)
                try:
                    r2 = fit_r2(d["asr"][idx], d["keff"][idx], d["eta"][idx])
                    cond_r2s.append(r2)
                    boot_r2_per_cond[method_name][cond].append(r2)
                except Exception:
                    pass

            if cond_r2s:
                boot_r2[method_name].append(np.mean(cond_r2s))

    # Results
    output = {"B": B, "seed": SEED, "n_panels": n_panels, "methods": {}}

    for method_name in METHODS:
        br = np.array(boot_r2[method_name])
        orig_r2s = []
        for ds, atk in conditions_list:
            cond = f"{ds}x{atk}"
            d = precomputed[method_name][cond]
            if len(d["asr"]) >= 10 and np.std(d["asr"]) >= 1e-10:
                orig_r2s.append(fit_r2(d["asr"], d["keff"], d["eta"]))

        output["methods"][method_name] = {
            "R2_original": float(np.mean(orig_r2s)),
            "R2_bootstrap_mean": float(np.mean(br)),
            "R2_bootstrap_ci_lower": float(np.percentile(br, 2.5)),
            "R2_bootstrap_ci_upper": float(np.percentile(br, 97.5)),
            "R2_bootstrap_std": float(np.std(br)),
        }

    # Pairwise differences
    pairwise = {}
    method_names = list(METHODS.keys())
    for i in range(len(method_names)):
        for j in range(i+1, len(method_names)):
            m1, m2 = method_names[i], method_names[j]
            b1 = np.array(boot_r2[m1])
            b2 = np.array(boot_r2[m2])
            n_min = min(len(b1), len(b2))
            diff = b1[:n_min] - b2[:n_min]
            pairwise[f"{m1}_minus_{m2}"] = {
                "diff_mean": float(np.mean(diff)),
                "diff_ci_lower": float(np.percentile(diff, 2.5)),
                "diff_ci_upper": float(np.percentile(diff, 97.5)),
                "prob_positive": float(np.mean(diff > 0)),
            }
    output["pairwise_differences"] = pairwise

    out_path = Path("/root/cert_manip_resist_eval/artifacts/results/plan001/aggregation_r2_bootstrap.json")
    with open(out_path, "w") as f:
        json.dump(output, f, indent=2, default=_json_default)
    print(f"\nSaved: {out_path}")

    # Print summary
    print("\n" + "="*80)
    print("BOOTSTRAP RESULTS (B=9999)")
    print("="*80)
    for m in METHODS:
        r = output["methods"][m]
        print(f"  {m:<18} R²={r['R2_original']:.4f}  "
              f"boot={r['R2_bootstrap_mean']:.4f}  "
              f"95% CI=[{r['R2_bootstrap_ci_lower']:.4f}, {r['R2_bootstrap_ci_upper']:.4f}]")

    print("\nPairwise differences:")
    for k, v in pairwise.items():
        ci_str = f"[{v['diff_ci_lower']:+.4f}, {v['diff_ci_upper']:+.4f}]"
        print(f"  {k:<50} diff={v['diff_mean']:+.4f}  CI={ci_str}  P(>0)={v['prob_positive']:.3f}")


